scriptData.script:
// Expanded Criticals: Test prompted when this critical is received (generated by tools/crit-tests.mjs).
// Rolled by the actor's player when the GM adds it (module setting "Who rolls critical Tests").
const api = game.modules.get("artantares-advanced-criticals")?.api;
if (!api?.rollCritTest) return ui.notifications.error("Expanded Criticals is not active: roll this critical's Test by hand.");
{
  const test = await api.rollCritTest(this, {skill: "Endurance", difficulty: "challenging", failure: "Dies from shock."});
  if (test) {
    if (test.failed) {
      await this.actor.addCondition("dead");
    }
    else {
      await api.gmNote(this, "Survives for Toughness Bonus days, then dies of complications unless magically healed first. Magical healing in time: survives, but contracts Blood Rot and a permanent Fatigued (2).");
    }
  }
}
